<template><section class="posts-page"><div class="module-page-header"><div><span class="eyebrow">CONTENT MANAGEMENT</span><h2>Bài viết</h2><p>Quản lý nội dung, bản nháp và các bài đã xuất bản trên website.</p></div><div class="header-actions"><div class="stat-box"><span>Đang hiển thị</span><strong>{{posts.length}}</strong></div><button class="primary-button" @click="openCreate">+ Thêm bài viết</button></div></div>
<div class="post-panel"><div class="post-filters"><div class="search-box"><span>⌕</span><input v-model="filters.search" placeholder="Tìm tiêu đề bài viết..." @keyup.enter="load"/></div><select v-model="filters.status" @change="load"><option value="">Tất cả trạng thái</option><option value="draft">Bản nháp</option><option value="published">Đã đăng</option></select><button @click="load">Tìm</button></div>
<div v-if="loading" class="state large">Đang tải...</div><div v-else-if="!posts.length" class="state large"><div class="empty-icon">✎</div><strong>Chưa có bài viết</strong><p>Tạo bài viết đầu tiên để nội dung xuất hiện trên website.</p><button class="primary-button" @click="openCreate">+ Thêm bài viết</button></div><div v-else class="post-table"><div class="post-head"><span>Bài viết</span><span>Slug</span><span>Trạng thái</span><span>Tác giả</span><span>Thao tác</span></div><article v-for="p in posts" :key="p.id" class="post-row"><div class="post-main"><div class="post-thumb"><img v-if="p.featured_image" :src="p.featured_image" :alt="p.title"/><span v-else>{{p.title.charAt(0).toUpperCase()}}</span></div><div><strong>{{p.title}}</strong><small>{{p.excerpt||'Không có mô tả ngắn'}}</small></div></div><code>{{p.slug}}</code><div><span class="post-status" :class="p.status">{{p.status==='published'?'Đã đăng':'Bản nháp'}}</span></div><span>{{p.author?.name||'—'}}</span><div class="row-actions"><button @click="openEdit(p)">Sửa</button><button class="danger" @click="remove(p)">Xóa</button></div></article></div></div>
<div v-if="showForm" class="modal-overlay" @click.self="showForm=false"><div class="post-modal"><div class="modal-head"><div><span class="eyebrow">BÀI VIẾT</span><h3>{{editing?'Chỉnh sửa bài viết':'Thêm bài viết mới'}}</h3></div><button @click="showForm=false">×</button></div><div class="post-form"><label><span>Tiêu đề *</span><input v-model="form.title"/></label><label><span>Slug</span><input v-model="form.slug" placeholder="Để trống để tự tạo"/></label><label class="full"><span>Mô tả ngắn</span><textarea v-model="form.excerpt" rows="3"/></label><label class="full"><span>Nội dung *</span><textarea v-model="form.content" rows="12" placeholder="Có thể nhập HTML bài viết"/></label><label class="full"><span>Ảnh đại diện URL</span><input v-model="form.featured_image" placeholder="https://..."/></label><label><span>Trạng thái</span><select v-model="form.status"><option value="draft">Bản nháp</option><option value="published">Đã đăng</option></select></label><label><span>Meta title</span><input v-model="form.meta_title"/></label><label class="full"><span>Meta description</span><textarea v-model="form.meta_description" rows="2"/></label></div><div class="modal-actions"><button @click="showForm=false">Hủy</button><button class="primary-button" @click="save">Lưu bài viết</button></div></div></div></section></template>
<script setup lang="ts">import{usePostsView}from'./PostsView.ts';const{posts,loading,showForm,editing,filters,form,load,openCreate,openEdit,save,remove}=usePostsView()</script><style scoped src="./PostsView.css"></style>
